__MODULES["components/QuickCommands"] = function()
    local QuickCommands = {}
    local State = __REQUIRE("state")
    local Constants = __REQUIRE("constants")
    local UIBuilder = __REQUIRE("utils/UIBuilder")
    local UIS = game:GetService("UserInputService")

    local function parseCommand(rawText)
        local trimmed = string.match(rawText, "^%s*(.-)%s*$") or ""
        local tokens = {}
        for word in string.gmatch(trimmed, "%S+") do
            table.insert(tokens, word)
        end
        local cmd = tokens[1] and tokens[1]:lower() or ""
        local args = {}
        for i = 2, #tokens do
            table.insert(args, tokens[i])
        end
        return cmd, args
    end

    function QuickCommands.init()
        local overlay = UIBuilder.create("TextButton", {
            Name = "QuickCommandsOverlay",
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            Text = "",
            AutoButtonColor = false,
            Visible = false,
            ZIndex = 9999,
            Parent = State.overlayContainer
        })

        local container = UIBuilder.create("Frame", {
            Size = UDim2.new(0, 440, 0, 44),
            Position = UDim2.new(0.5, 0, 0.2, 0),
            AnchorPoint = Vector2.new(0.5, 0),
            BackgroundColor3 = Constants.Colors.dark,
            BorderSizePixel = 0,
            Parent = overlay
        })
        UIBuilder.create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = container })

        local drag = Instance.new("UIDragDetector")
        drag.ResponseStyle = Enum.UIDragDetectorResponseStyle.Scale
        drag.Parent = container

        local inner = UIBuilder.create("Frame", {
            Size = UDim2.new(1, -2, 1, -2),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = Constants.Colors.dark,
            BorderSizePixel = 0,
            Parent = container
        })
        UIBuilder.create("UICorner", { CornerRadius = UDim.new(0, 7), Parent = inner })

        local gradient = UIBuilder.createGradient(container)
        gradient.Visible = true 

        local autoCompleteLabel = UIBuilder.create("TextLabel", {
            Size = UDim2.new(1, -20, 1, 0),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            TextColor3 = Color3.fromRGB(150, 150, 150),
            Text = "",
            FontFace = Constants.Fonts.regular,
            TextSize = 16,
            TextXAlignment = Enum.TextXAlignment.Left,
            Active = false,
            Parent = inner
        })

        local searchBox = UIBuilder.create("TextBox", {
            Size = UDim2.new(1, -20, 1, 0),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            TextColor3 = Constants.Colors.text,
            PlaceholderColor3 = Constants.Colors.textPlaceholder,
            PlaceholderText = "Search commands...",
            FontFace = Constants.Fonts.regular,
            TextSize = 16,
            TextXAlignment = Enum.TextXAlignment.Left,
            ClearTextOnFocus = false,
            ClipsDescendants = true,
            Parent = inner
        })

        local resultsScroll = UIBuilder.create("ScrollingFrame", {
            Size = UDim2.new(1, 0, 0, 0),
            Position = UDim2.new(0, 0, 1, 8),
            BackgroundColor3 = Constants.Colors.dark,
            BorderSizePixel = 0,
            ScrollBarThickness = 4,
            Parent = container
        })
        UIBuilder.create("UICorner", { CornerRadius = UDim.new(0, 8), Parent = resultsScroll })
        local _listLayout = UIBuilder.create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Padding = UDim.new(0, 2), Parent = resultsScroll })

        local function close()
            overlay.Visible = false
            searchBox.Text = ""
            autoCompleteLabel.Text = ""
            if searchBox:IsFocused() then
                searchBox:ReleaseFocus()
            end
        end

        local function open()
            overlay.Visible = true
            searchBox.Text = ""
            autoCompleteLabel.Text = ""
            overlay.ZIndex = State.getHighestZ() + 100

            task.defer(function()
                searchBox.Text = ""
                searchBox:CaptureFocus()
                searchBox.Text = ""
                searchBox.CursorPosition = 1
            end)
        end

        overlay.Activated:Connect(close)

        State.toggleQuickCommands = function()
            if overlay.Visible then close() else open() end
        end

        local currentFirstCommand = nil
        local currentFirstMatchedName = ""

        local function updateResults()
            if string.find(searchBox.Text, "\t") then
                searchBox.Text = string.gsub(searchBox.Text, "\t", "")
                searchBox.CursorPosition = #searchBox.Text + 1
            end

            local queryCmd, args = parseCommand(searchBox.Text)
            currentFirstCommand = nil
            currentFirstMatchedName = ""
            autoCompleteLabel.Text = ""

            for _, child in ipairs(resultsScroll:GetChildren()) do
                if child:IsA("Frame") then child:Destroy() end
            end

            if queryCmd == "" then
                resultsScroll.Size = UDim2.new(1, 0, 0, 0)
                return
            end

            -- match priority: exact > prefix > substring
            local matches = {}

            for _, cmdData in pairs(State.commands) do
                local titleLower = cmdData.title:lower()
                local idLower = cmdData.id:lower()
                local bestScore = 999
                local bestMatchedKey = cmdData.title

                if titleLower == queryCmd or idLower == queryCmd then
                    bestScore = 1
                    bestMatchedKey = cmdData.title
                elseif titleLower:sub(1, #queryCmd) == queryCmd then
                    bestScore = math.min(bestScore, 2)
                    bestMatchedKey = cmdData.title
                elseif titleLower:find(queryCmd, 1, true) then
                    bestScore = math.min(bestScore, 3)
                    bestMatchedKey = cmdData.title
                end

                for _, alias in ipairs(cmdData.aliases or {}) do
                    local aLower = alias:lower()
                    if aLower == queryCmd then
                        bestScore = 1
                        bestMatchedKey = alias
                        break
                    elseif aLower:sub(1, #queryCmd) == queryCmd then
                        if bestScore > 2 then
                            bestScore = 2
                            bestMatchedKey = alias
                        end
                    elseif aLower:find(queryCmd, 1, true) then
                        if bestScore > 3 then
                            bestScore = 3
                            bestMatchedKey = alias
                        end
                    end
                end

                if bestScore < 999 then
                    table.insert(matches, {
                        cmd = cmdData,
                        score = bestScore,
                        matchedKey = bestMatchedKey
                    })
                end
            end

            table.sort(matches, function(a, b)
                if a.score ~= b.score then
                    return a.score < b.score
                end
                return a.cmd.title < b.cmd.title
            end)

            for i, match in ipairs(matches) do
                local cmdData = match.cmd
                local matchedKey = match.matchedKey

                local resFrame = UIBuilder.create("Frame", {
                    Size = UDim2.new(1, 0, 0, 32),
                    BackgroundColor3 = Constants.Colors.darkHover,
                    BorderSizePixel = 0,
                    ClipsDescendants = true,
                    Parent = resultsScroll
                })
                UIBuilder.create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = resFrame })

                local aliasStr = ""
                if cmdData.aliases and #cmdData.aliases > 0 then
                    aliasStr = " [" .. table.concat(cmdData.aliases, ", ") .. "]"
                end
                local usageStr = cmdData.usage ~= "" and (" " .. cmdData.usage) or ""

                local resBtn = UIBuilder.create("TextButton", {
                    Size = UDim2.new(1, 0, 1, 0),
                    BackgroundTransparency = 1,
                    Text = "  " .. cmdData.title .. aliasStr .. usageStr,
                    TextColor3 = Constants.Colors.text,
                    FontFace = Constants.Fonts.medium,
                    TextSize = 13,
                    TextXAlignment = Enum.TextXAlignment.Left,
                    TextTruncate = Enum.TextTruncate.AtEnd,
                    Parent = resFrame
                })

                local function execute()
                    local _, currentArgs = parseCommand(searchBox.Text)
                    task.spawn(function()
                        cmdData.execute(currentArgs)
                    end)
                    close()
                end

                if i == 1 then
                    currentFirstCommand = cmdData
                    currentFirstMatchedName = matchedKey
                    resBtn.TextColor3 = Constants.Colors.accent

                    if #args == 0 and string.sub(matchedKey:lower(), 1, #queryCmd) == queryCmd then
                        autoCompleteLabel.Text = queryCmd .. string.sub(matchedKey, #queryCmd + 1) .. usageStr
                    end
                end

                resBtn.Activated:Connect(execute)
            end

            local resultHeight = math.min(#matches * 34, 220)
            resultsScroll.Size = UDim2.new(1, 0, 0, resultHeight)
            resultsScroll.CanvasSize = UDim2.new(0, 0, 0, #matches * 34)
        end

        searchBox:GetPropertyChangedSignal("Text"):Connect(updateResults)

        searchBox.FocusLost:Connect(function(enterPressed)
            if enterPressed then
                if currentFirstCommand then
                    local _, args = parseCommand(searchBox.Text)
                    task.spawn(function()
                        currentFirstCommand.execute(args)
                    end)
                end
                close()
            end
        end)

        UIS.InputBegan:Connect(function(input)
            if searchBox:IsFocused() and input.KeyCode == Enum.KeyCode.Tab and currentFirstMatchedName ~= "" then
                searchBox.Text = currentFirstMatchedName .. " "
                searchBox.CursorPosition = #searchBox.Text + 1
                task.defer(function()
                    searchBox.Text = string.gsub(searchBox.Text, "\t", "")
                    searchBox.CursorPosition = #searchBox.Text + 1
                    searchBox:CaptureFocus()
                end)
            end
        end)
    end

    return QuickCommands
end

__MODULES["components/Selection"] = function()
    local Selection = {}
    local State = __REQUIRE("state")
    local Constants = __REQUIRE("constants")
    local UIBuilder = __REQUIRE("utils/UIBuilder")

    function Selection.create(tabObj, config, parentOverride)
        local parent = parentOverride or tabObj.tabData.scroll
        local info = config.Info or {}
        local internalInfo = config.InternalInfo or {}
        local commandId = internalInfo.UniqueCommandId or Constants.randomString()
        local aliases = config.Aliases or info.Aliases or internalInfo.Aliases or {}

        local isSingleSelect = config.SingleSelect == true or internalInfo.SingleSelect == true
        local isBindable = internalInfo.Bindable or false
        local isStartup = internalInfo.StartupAvailable or false
        local callback = config.Callback or function() end

        State.values[commandId] = State.values[commandId] or config.DefaultValue or nil

        local frame = UIBuilder.create("Frame", {
            Name = "frame",
            BackgroundColor3 = Constants.Colors.dark,
            BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 0, 20),
            ClipsDescendants = true,
            Parent = parent
        })

        local header = UIBuilder.create("Frame", {
            Size = UDim2.new(1, 0, 0, 20),
            BackgroundTransparency = 1,
            BorderSizePixel = 0,
            ClipsDescendants = true,
            Parent = frame
        })

        local button = UIBuilder.create("ImageButton", {
            Size = UDim2.new(1, -20, 1, 0),
            BackgroundTransparency = 1,
            Parent = header
        })

        local text = UIBuilder.create("TextLabel", {
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            TextColor3 = Constants.Colors.text,
            FontFace = Constants.Fonts.regular,
            TextSize = 14,
            TextXAlignment = Enum.TextXAlignment.Left,
            Text = info.Title or "Selection",
            TextTruncate = Enum.TextTruncate.AtEnd,
            ClipsDescendants = true,
            Active = false,
            Parent = button
        })
        UIBuilder.create("UIPadding", { PaddingLeft = UDim.new(0, 3), Parent = text })

        local more = UIBuilder.create("ImageButton", {
            Size = UDim2.new(0, 20, 0, 20),
            Position = UDim2.new(1, -2, 0.5, 0),
            AnchorPoint = Vector2.new(1, 0.5),
            BackgroundTransparency = 1,
            Parent = header
        })

        local img = UIBuilder.create("ImageLabel", {
            Size = UDim2.new(0, 10, 0, 10),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            Image = "rbxassetid://71488146016369",
            ImageColor3 = Constants.Colors.gray,
            Active = false,
            Parent = more
        })

        local gradient = UIBuilder.createGradient(frame)

        local function formatSummaryText(summaryText)
            if not summaryText or type(summaryText) == "table" then return info.Title or "" end
            return (info.Title or "") .. " - " .. tostring(summaryText)
        end

        local function updateSelectionVisuals()
            gradient.Visible = State.values[commandId] ~= nil
        end

        button.MouseEnter:Connect(function() 
            frame.BackgroundColor3 = Constants.darkenColor(Constants.Colors.dark, 0.02) 
            if info.Description then State.showTooltip(info.Description) end
        end)
        button.MouseLeave:Connect(function() 
            frame.BackgroundColor3 = Constants.Colors.dark 
            if info.Description then State.hideTooltip(info.Description) end
        end)

        local function executeCommand()
            if type(callback) == "function" then
                local val = State.values[commandId]
                if type(val) == "table" and #val > 0 then
                    callback(table.unpack(val))
                else
                    callback(val)
                end
            end
        end
        button.Activated:Connect(executeCommand)

        local childOptions = {}
        local activeOptionButtons = {}

        local function addOption(childConfig)
            local selectionValue = childConfig.Value or (childConfig.Info and childConfig.Info.Title) or Constants.randomString()
            local cfg = {
                Info = childConfig.Info,
                InternalInfo = { Toggle = true, UniqueCommandId = childConfig.InternalInfo and childConfig.InternalInfo.UniqueCommandId or Constants.randomString() },
                Callback = nil
            }

            cfg.Callback = function(state)
                if isSingleSelect then
                    if state then
                        State.values[commandId] = selectionValue
                        for val, optBtn in pairs(activeOptionButtons) do
                            if val ~= selectionValue and optBtn.setVisualState then optBtn.setVisualState(false) end
                        end
                    else
                        if State.values[commandId] == selectionValue then State.values[commandId] = nil end
                    end
                end
                if childConfig.Callback then childConfig.Callback(state, State.values[commandId]) end
                updateSelectionVisuals()
            end

            table.insert(childOptions, { cfg = cfg, val = selectionValue, ogConfig = childConfig, type = "Button" })
            return { UpdateSummary = function(_, txt) text.Text = formatSummaryText(txt) end }
        end

        more.Activated:Connect(function()
            local ownerKey = commandId .. "::"
            local opened = tabObj:openMore(ownerKey, frame, function(moreScroll)
                activeOptionButtons = {}
                for _, opt in ipairs(childOptions) do
                    if opt.type == "Button" then
                        local Button = __REQUIRE("components/Button")
                        local btn = Button.create(tabObj, opt.cfg, moreScroll)
                        local valKey = opt.val or (opt.cfg.Info and opt.cfg.Info.Title) or Constants.randomString()
                        activeOptionButtons[valKey] = btn
                        if State.values[commandId] == valKey then btn.setVisualState(true) end
                    elseif opt.type == "TextBox" then
                        __REQUIRE("components/Input").create(tabObj, opt.cfg, moreScroll)
                    elseif opt.type == "Slider" then
                        __REQUIRE("components/Slider").create(tabObj, opt.cfg, moreScroll)
                    elseif opt.type == "Label" then
                        __REQUIRE("components/Label").create(tabObj, opt.cfg, moreScroll)
                    end
                end
            end, function()
                img.ImageColor3 = Constants.Colors.gray
            end)

            img.ImageColor3 = opened and Constants.Colors.accent or Constants.Colors.gray
        end)

        if (isBindable or isStartup) and not parentOverride then
            button.MouseButton2Down:Connect(function()
                local ownerKey = commandId .. "::bind"
                tabObj:openMore(ownerKey, frame, function(moreScroll)
                    tabObj:buildContextMenu(moreScroll, commandId, isBindable, isStartup, executeCommand)
                end, function() img.ImageColor3 = Constants.Colors.gray end)
                img.ImageColor3 = Constants.Colors.accent
            end)
        end

        State.registerCommand({
            id = commandId,
            title = info.Title or "Selection",
            aliases = aliases,
            description = info.Description or "",
            type = "Selection",
            usage = "<option>",
            execute = function(args)
                if #args > 0 then
                    local query = table.concat(args, " "):lower()
                    for _, opt in ipairs(childOptions) do
                        local optVal = tostring(opt.val or "")
                        local optTitle = tostring(opt.cfg and opt.cfg.Info and opt.cfg.Info.Title or "")
                        if optVal:lower():find(query, 1, true) or optTitle:lower():find(query, 1, true) then
                            if isSingleSelect then
                                State.values[commandId] = opt.val
                                updateSelectionVisuals()
                                if opt.cfg and opt.cfg.Callback then
                                    opt.cfg.Callback(true)
                                elseif callback then
                                    callback(opt.val)
                                end
                            else
                                if opt.cfg and opt.cfg.Callback then
                                    opt.cfg.Callback(true)
                                end
                            end
                            return
                        end
                    end
                else
                    if isSingleSelect and #childOptions > 0 then
                        local currentIdx = 1
                        for idx, opt in ipairs(childOptions) do
                            if State.values[commandId] == opt.val then
                                currentIdx = idx
                                break
                            end
                        end
                        local nextIdx = (currentIdx % #childOptions) + 1
                        local nextOpt = childOptions[nextIdx]
                        if nextOpt then
                            State.values[commandId] = nextOpt.val
                            updateSelectionVisuals()
                            if nextOpt.cfg and nextOpt.cfg.Callback then
                                nextOpt.cfg.Callback(true)
                            elseif callback then
                                callback(nextOpt.val)
                            end
                        end
                    end
                end
            end
        })

        return {
            getValue = function() return State.values[commandId] end,
            GetValue = function() return State.values[commandId] end,
            SetValue = function(_, v) State.values[commandId] = v; updateSelectionVisuals() end,
            UpdateSummary = function(_, txt) text.Text = formatSummaryText(txt) end,
            AddButton = function(self, cfg)
                if isSingleSelect then return addOption(cfg) end
                local btnVal = cfg.Value or (cfg.Info and cfg.Info.Title) or (cfg.InternalInfo and cfg.InternalInfo.UniqueCommandId) or Constants.randomString()
                table.insert(childOptions, { cfg = cfg, val = btnVal, type = "Button" })
                return self
            end,
            AddOption = function(self, cfg) return addOption(cfg) end,
            AddTextBox = function(self, cfg) 
                local val = cfg.Value or (cfg.Info and cfg.Info.Title) or Constants.randomString()
                table.insert(childOptions, { cfg = cfg, val = val, type = "TextBox" })
                return self 
            end,
            AddSlider = function(self, cfg) 
                local val = cfg.Value or (cfg.Info and cfg.Info.Title) or Constants.randomString()
                table.insert(childOptions, { cfg = cfg, val = val, type = "Slider" })
                return self 
            end,
            AddLabel = function(self, cfg)
                table.insert(childOptions, { cfg = cfg, type = "Label" })
                return self
            end
        }
    end

    return Selection
end

__MODULES["components/Slider"] = function()
    local Slider = {}
    local State = __REQUIRE("state")
    local Constants = __REQUIRE("constants")
    local UIBuilder = __REQUIRE("utils/UIBuilder")
    local UIS = game:GetService("UserInputService")
    local ConfigManager = __REQUIRE("config/ConfigManager")

    function Slider.create(tabObj, config, parentOverride)
        local parent = parentOverride or tabObj.tabData.scroll
        local info = config.Info or {}
        local internalInfo = config.InternalInfo or {}
        local commandId = internalInfo.UniqueCommandId or Constants.randomString()

        local isBindable = internalInfo.Bindable or false
        local isStartup = internalInfo.StartupAvailable or false
        local callback = config.Callback or function() end
        local aliases = config.Aliases or info.Aliases or internalInfo.Aliases or {}

        local shouldSave = config.Save == true or internalInfo.Save == true or (config.Settings and config.Settings.save == true) or false

        local min = config.Min or 0
        local max = config.Max or 100
        local default = config.Default or min
        local step = config.Step or 1
        local sliderType = config.SliderType or "number"

        if sliderType == "bool" then
            min, max, step = 0, 1, 1
            default = default and 1 or 0
        end

        local frame = UIBuilder.create("Frame", {
            Name = "frame",
            BackgroundColor3 = Constants.Colors.dark,
            BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 0, 35),
            ClipsDescendants = true,
            Parent = parent
        })

        local text = UIBuilder.create("TextLabel", {
            Name = "text",
            FontFace = Constants.Fonts.regular,
            TextColor3 = Constants.Colors.text,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextSize = 14,
            Size = UDim2.new(1, -50, 0, 20),
            Position = UDim2.new(0, 0, 0, 0),
            TextTruncate = Enum.TextTruncate.AtEnd,
            ClipsDescendants = true,
            Active = false,
            Parent = frame
        })
        UIBuilder.create("UIPadding", { PaddingLeft = UDim.new(0, 3), Parent = text })

        local valueText = UIBuilder.create("TextLabel", {
            Name = "valueText",
            FontFace = Constants.Fonts.regular,
            TextColor3 = Constants.Colors.accent,
            BackgroundTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Right,
            TextSize = 14,
            Size = UDim2.new(0, 50, 0, 20),
            Position = UDim2.new(1, -6, 0, 0),
            AnchorPoint = Vector2.new(1, 0),
            Active = false,
            Parent = frame
        })

        local track = UIBuilder.create("Frame", {
            Name = "track",
            BackgroundColor3 = Constants.Colors.inputBg,
            BorderSizePixel = 0,
            Size = UDim2.new(1, -12, 0, 4),
            Position = UDim2.new(0, 6, 0, 25),
            Parent = frame
        })

        local fill = UIBuilder.create("Frame", {
            Name = "fill",
            BackgroundColor3 = Constants.Colors.accent,
            BorderSizePixel = 0,
            Size = UDim2.new(0, 0, 1, 0),
            Active = false,
            Parent = track
        })

        local thumb = UIBuilder.create("ImageButton", {
            Name = "thumb",
            BackgroundColor3 = Constants.Colors.text,
            BorderSizePixel = 0,
            Size = UDim2.new(0, 8, 0, 14),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0, 0, 0.5, 0),
            Parent = track
        })
        UIBuilder.create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = thumb })

        frame.MouseEnter:Connect(function() 
            frame.BackgroundColor3 = Constants.darkenColor(Constants.Colors.dark, 0.02) 
            if info.Description then State.showTooltip(info.Description) end
        end)
        frame.MouseLeave:Connect(function() 
            frame.BackgroundColor3 = Constants.Colors.dark 
            if info.Description then State.hideTooltip(info.Description) end
        end)

        local function updateVisuals(value)
            local percent = (sliderType == "bool") and (value == 1 and 1 or 0) or math.clamp((value - min) / (max - min), 0, 1)
            fill.Size = UDim2.new(percent, 0, 1, 0)
            thumb.Position = UDim2.new(percent, 0, 0.5, 0)

            if sliderType == "bool" then
                valueText.Text = value == 1 and "On" or "Off"
            else
                valueText.Text = tostring(value)
            end
        end

        local currentVal = default
        if shouldSave then
            local saved = ConfigManager.get("Settings")[commandId]
            if saved ~= nil then currentVal = saved end
        end

        State.values[commandId] = currentVal
        text.Text = info.Title or "Slider"
        updateVisuals(currentVal)

        local isDragging = false
        local lastFiredVal = currentVal

        local function applyValue(val, forceCallback)
            val = math.clamp(val, min, max)
            if sliderType == "bool" then
                val = val >= 0.5 and 1 or 0
            else
                val = math.floor((val / step) + 0.5) * step
                val = math.clamp(val, min, max)
            end

            if forceCallback or val ~= lastFiredVal then
                lastFiredVal = val
                State.values[commandId] = val
                updateVisuals(val)
                callback(val)
                if shouldSave then
                    ConfigManager.set(commandId, val, "Settings")
                end
            end
        end

        local function updateDrag(input)
            local relativeX = math.clamp(input.Position.X - track.AbsolutePosition.X, 0, track.AbsoluteSize.X)
            local percent = relativeX / track.AbsoluteSize.X
            local val = min + (max - min) * percent
            applyValue(val, false)
        end

        thumb.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDragging = true
            end
        end)
        track.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDragging = true
                updateDrag(input)
            end
        end)

        UIS.InputChanged:Connect(function(input)
            if isDragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
                updateDrag(input)
            end
        end)

        UIS.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                isDragging = false
            end
        end)

        if (isBindable or isStartup) and not parentOverride then
            frame.InputBegan:Connect(function(input)
                if input.UserInputType == Enum.UserInputType.MouseButton2 then
                    local ownerKey = commandId .. "::"
                    tabObj:openMore(ownerKey, frame, function(moreScroll)
                        tabObj:buildContextMenu(moreScroll, commandId, isBindable, isStartup, function()
                            if sliderType == "bool" then
                                local newVal = State.values[commandId] == 1 and 0 or 1
                                applyValue(newVal, true)
                            end
                        end)
                    end)
                end
            end)
        end

        State.registerCommand({
            id = commandId,
            title = info.Title or "Slider",
            aliases = aliases,
            description = info.Description or "",
            type = "Slider",
            usage = sliderType == "bool" and "[on/off]" or ("<" .. tostring(min) .. "-" .. tostring(max) .. ">"),
            execute = function(args)
                if #args > 0 then
                    if sliderType == "bool" then
                        local a = tostring(args[1]):lower()
                        applyValue((a == "on" or a == "1" or a == "true") and 1 or 0, true)
                    else
                        local num = tonumber(args[1])
                        if num then applyValue(num, true) end
                    end
                else
                    if sliderType == "bool" then
                        local newVal = State.values[commandId] == 1 and 0 or 1
                        applyValue(newVal, true)
                    else
                        applyValue(State.values[commandId] or default, true)
                    end
                end
            end
        })

        return {
            getValue = function() return State.values[commandId] end,
            getId = function() return commandId end,
            setValue = function(_, val) applyValue(val, true) end
        }
    end

    return Slider
end

__MODULES["components/Tab"] = function()
    local Tab = {}
    local State = __REQUIRE("state")
    local Constants = __REQUIRE("constants")
    local UIBuilder = __REQUIRE("utils/UIBuilder")
    local ConfigManager = __REQUIRE("config/ConfigManager")
    local TS = game:GetService("TweenService")
    local GuiService = game:GetService("GuiService")

    local function getViewport()
        local camera = workspace.CurrentCamera
        return (camera and camera.ViewportSize) or Vector2.new(1280, 720)
    end

    local function clampPosition(pos)
        local vp = getViewport()
        local topInset = GuiService:GetGuiInset().Y
        local x = math.clamp(pos.X.Offset, 10, math.max(10, vp.X - 210))
        local y = math.clamp(pos.Y.Offset, topInset + 5, math.max(topInset + 5, vp.Y - 25))
        return UDim2.new(0, x, 0, y)
    end

    local function snapValue(val, step)
        return math.round(val / step) * step
    end

    function Tab.create(tabName, defaultPosition)
        State.tabCount = (State.tabCount or 0) + 1
        if not table.find(State.tabOrder, tabName) then
            table.insert(State.tabOrder, tabName)
        end

        local topInset = GuiService:GetGuiInset().Y
        local savedPositions = ConfigManager.get("TabPositions") or {}
        local savedPos = savedPositions[tabName]

        local initialPosition
        if savedPos and savedPos.X and savedPos.Y then
            local vp = getViewport()
            local x = (savedPos.X[1] * vp.X) + savedPos.X[2]
            local y = (savedPos.Y[1] * vp.Y) + savedPos.Y[2]
            initialPosition = clampPosition(UDim2.new(0, math.round(x), 0, math.round(y)))
        elseif defaultPosition then
            initialPosition = clampPosition(defaultPosition)
        else
            local yOffset = topInset + 10 + ((State.tabCount - 1) * 26)
            initialPosition = clampPosition(UDim2.new(0, 15, 0, yOffset))
        end

        local tab = UIBuilder.create("TextLabel", {
            Name = tabName,
            Text = tabName,
            TextColor3 = Constants.Colors.text,
            BackgroundColor3 = Constants.Colors.accent,
            BorderSizePixel = 0,
            FontFace = Constants.Fonts.medium,
            TextSize = 18,
            Size = UDim2.new(0, 200, 0, 20),
            Position = initialPosition,
            AnchorPoint = Vector2.new(0, 0),
            ClipsDescendants = false,
            Parent = State.tabsContainer
        })

        local drag = Instance.new("UIDragDetector")
        drag.ResponseStyle = Enum.UIDragDetectorResponseStyle.Offset
        drag.Parent = tab

        pcall(function()
            drag:AddConstraintFunction(1, function(proposedMotion, proposedRotation)
                local settings = ConfigManager.get("Settings") or {}
                if settings.GridSnap == false then
                    return proposedMotion, proposedRotation
                end
                local gridSize = settings.GridSize or 15
                local snappedX = snapValue(proposedMotion.X.Offset, gridSize)
                local snappedY = snapValue(proposedMotion.Y.Offset, gridSize)
                return UDim2.new(0, snappedX, 0, snappedY), proposedRotation
            end)
        end)

        drag.DragEnd:Connect(function()
            local settings = ConfigManager.get("Settings") or {}
            local useGrid = settings.GridSnap ~= false
            local gridSize = settings.GridSize or 15

            local finalX = tab.Position.X.Offset
            local finalY = tab.Position.Y.Offset

            if useGrid then
                finalX = snapValue(finalX, gridSize)
                finalY = snapValue(finalY, gridSize)
            end

            local clamped = clampPosition(UDim2.new(0, finalX, 0, finalY))
            tab.Position = clamped

            ConfigManager.set(tabName, {
                X = { 0, clamped.X.Offset },
                Y = { 0, clamped.Y.Offset }
            }, "TabPositions")
        end)

        local camera = workspace.CurrentCamera
        if camera then
            camera:GetPropertyChangedSignal("ViewportSize"):Connect(function()
                local clamped = clampPosition(tab.Position)
                if clamped ~= tab.Position then
                    tab.Position = clamped
                end
            end)
        end

        local isMinimized = true
        local isAnimating = false

        local openMin = UIBuilder.create("ImageButton", {
            Name = "openMin",
            BackgroundTransparency = 1,
            Size = UDim2.new(0, 20, 0, 20),
            AnchorPoint = Vector2.new(0.5, 0.5),
            Position = UDim2.new(0, 10, 0.5, 0),
            Rotation = isMinimized and 180 or 0,
            Image = isMinimized and "rbxassetid://11295291707" or "rbxassetid://11293980042",
            Parent = tab
        })

        local scroll = UIBuilder.create("ScrollingFrame", {
            Name = "scroll",
            Visible = false,
            ScrollBarThickness = 6,
            Size = UDim2.new(1, 0, 0, 0),
            Position = UDim2.new(0, 0, 0, 20),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            CanvasSize = UDim2.new(0,0,0,0),
            BackgroundColor3 = Constants.Colors.dark,
            BorderSizePixel = 0,
            ClipsDescendants = true,
            Parent = tab
        })
        local scrollList = UIBuilder.create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = scroll })

        local moreBlocker = UIBuilder.create("TextButton", {
            Name = "moreBlocker",
            Size = UDim2.new(100, 0, 100, 0),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundTransparency = 1,
            Text = "",
            Visible = false,
            Parent = tab
        })

        local moreScroll = UIBuilder.create("ScrollingFrame", {
            Name = "moreScroll",
            Visible = false,
            ScrollBarThickness = 6,
            Size = UDim2.new(1, 0, 0, 120),
            Position = UDim2.new(1, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
            CanvasSize = UDim2.new(0,0,0,0),
            BackgroundColor3 = Constants.Colors.dark,
            BorderSizePixel = 0,
            ClipsDescendants = true,
            Parent = tab
        })
        local moreList = UIBuilder.create("UIListLayout", { SortOrder = Enum.SortOrder.LayoutOrder, Parent = moreScroll })

        local function bindDynamicSize(scrollingFrame, listLayout, minHeight)
            local function refresh()
                if isMinimized or isAnimating then return end
                local desired = math.max(minHeight or 20, listLayout.AbsoluteContentSize.Y)
                local vp = getViewport()
                local maxHeight = math.max(minHeight or 20, vp.Y - scrollingFrame.AbsolutePosition.Y - 40)
                local clamped = math.min(desired, maxHeight)
                scrollingFrame.Size = UDim2.new(scrollingFrame.Size.X.Scale, scrollingFrame.Size.X.Offset, 0, clamped)
            end

            listLayout:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(refresh)
            scrollingFrame:GetPropertyChangedSignal("AbsolutePosition"):Connect(refresh)
            scrollingFrame:GetPropertyChangedSignal("AbsoluteSize"):Connect(refresh)

            if camera then
                camera:GetPropertyChangedSignal("ViewportSize"):Connect(refresh)
            end

            return refresh
        end

        local refreshScrollSize = bindDynamicSize(scroll, scrollList, 20)
        local refreshMoreSize = bindDynamicSize(moreScroll, moreList, 20)

        local currentOnClose = nil

        local function closeMore()
            moreScroll.Visible = false
            moreBlocker.Visible = false
            moreScroll:SetAttribute("Owner", nil)
            if currentOnClose then 
                currentOnClose()
                currentOnClose = nil
            end
        end
        moreBlocker.Activated:Connect(closeMore)

        local function calculateTargetHeight()
            local desired = math.max(20, scrollList.AbsoluteContentSize.Y)
            local vp = getViewport()
            local maxHeight = math.max(20, vp.Y - tab.AbsolutePosition.Y - 80)
            return math.min(desired, maxHeight)
        end

        openMin.Activated:Connect(function()
            if isAnimating then return end
            isAnimating = true
            tab.ZIndex = State.getHighestZ() + 1
            isMinimized = not isMinimized

            if isMinimized then
                closeMore()
                openMin.Image = "rbxassetid://11295291707"
                TS:Create(openMin, TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), { Rotation = 180 }):Play()

                local foldTween = TS:Create(scroll, TweenInfo.new(0.26, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), { Size = UDim2.new(1, 0, 0, 0) })
                foldTween:Play()
                foldTween.Completed:Connect(function()
                    if isMinimized then scroll.Visible = false end
                    isAnimating = false
                end)
            else
                openMin.Image = "rbxassetid://11293980042"
                scroll.Visible = true
                scroll.Size = UDim2.new(1, 0, 0, 0)
                TS:Create(openMin, TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), { Rotation = 0 }):Play()

                local targetH = calculateTargetHeight()
                local expandTween = TS:Create(scroll, TweenInfo.new(0.3, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), { Size = UDim2.new(1, 0, 0, targetH) })
                expandTween:Play()
                expandTween.Completed:Connect(function()
                    isAnimating = false
                    refreshScrollSize()
                end)
            end
        end)

        tab.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                tab.ZIndex = State.getHighestZ() + 1
            end
        end)

        tab:GetPropertyChangedSignal("AbsolutePosition"):Connect(function()
            if not isMinimized and not isAnimating then
                refreshScrollSize()
            end
            refreshMoreSize()
        end)

        local tabData = {
            frame = tab,
            scroll = scroll,
            moreScroll = moreScroll,
            refreshMoreSize = refreshMoreSize,
            closeMoreFunc = closeMore
        }
        State.tabs[tabName] = tabData
        tab.ZIndex = State.getHighestZ() + 1

        local tabObj = {}
        tabObj.name = tabName
        tabObj.tabData = tabData

        function tabObj:AddButton(config, pOverride) return __REQUIRE("components/Button").create(self, config, pOverride) end
        function tabObj:AddInput(config, pOverride) return __REQUIRE("components/Input").create(self, config, pOverride) end
        function tabObj:AddTextBox(config, pOverride) return self:AddInput(config, pOverride) end
        function tabObj:AddTextbox(config, pOverride) return self:AddInput(config, pOverride) end
        function tabObj:AddSelection(config, pOverride) return __REQUIRE("components/Selection").create(self, config, pOverride) end
        function tabObj:AddSlider(config, pOverride) return __REQUIRE("components/Slider").create(self, config, pOverride) end
        function tabObj:AddLabel(config, pOverride) return __REQUIRE("components/Label").create(self, config, pOverride) end
        function tabObj:GetFrame() return tab end
        function tabObj:closeMore() closeMore() end

        function tabObj:openMore(ownerKey, sourceFrame, populateFunc, onCloseFunc)
            tab.ZIndex = State.getHighestZ() + 1
            for _, child in ipairs(moreScroll:GetChildren()) do
                if child:IsA("Frame") or child:IsA("TextButton") then child:Destroy() end
            end

            if moreScroll.Visible and moreScroll:GetAttribute("Owner") == ownerKey then
                self:closeMore()
                return false
            end

            State.hideAllMoreScrolls()
            moreScroll:SetAttribute("Owner", ownerKey)
            currentOnClose = onCloseFunc

            moreBlocker.ZIndex = tab.ZIndex + 5
            moreScroll.ZIndex = moreBlocker.ZIndex + 1
            moreBlocker.Visible = true
            moreScroll.Visible = true

            -- screen bounds checka
            local vp = getViewport()
            local tabX = tab.AbsolutePosition.X
            local moreWidth = 200
            local hasRightRoom = (tabX + 200 + moreWidth + 10 <= vp.X)
            local hasLeftRoom = (tabX >= moreWidth + 10)
            local placeOnLeft = not hasRightRoom and hasLeftRoom

            local xOffset = placeOnLeft and (-moreWidth - 4) or 204

            local sourceY = sourceFrame.AbsolutePosition.Y
            local relativeY = sourceY - tab.AbsolutePosition.Y
            local approxHeight = 150
            local overflowY = (sourceY + approxHeight) - (vp.Y - 20)
            if overflowY > 0 then
                relativeY = math.max(0, relativeY - overflowY)
            end

            moreScroll.Position = UDim2.new(0, xOffset, 0, relativeY)

            populateFunc(moreScroll)
            task.defer(refreshMoreSize)
            return true
        end

        function tabObj:buildContextMenu(moreScrollFrame, commandId, isBindable, isStartup, callback, updateTextFunc)
            local UIS = game:GetService("UserInputService")
            local KeybindManager = __REQUIRE("config/KeybindManager")

            if isBindable then
                local assignBtn = self:AddButton({ Info = { Title = "Assign a New Keybind" } }, moreScrollFrame)
                assignBtn.button.Activated:Connect(function()
                    assignBtn.text.Text = "Press a key (timeout: 5s)"
                    assignBtn.text.TextColor3 = Constants.Colors.accent

                    local conn, timeoutConn
                    local timedOut = false
                    timeoutConn = task.delay(5, function()
                        timedOut = true
                        assignBtn.text.Text = "Assign a New Keybind"
                        assignBtn.text.TextColor3 = Constants.Colors.text
                        if conn then conn:Disconnect() end
                    end)

                    conn = UIS.InputBegan:Connect(function(input)
                        if UIS:GetFocusedTextBox() then return end
                        if timedOut then return end

                        if input.UserInputType == Enum.UserInputType.Keyboard then
                            timedOut = true
                            KeybindManager.bind(commandId, callback, input.KeyCode)
                            conn:Disconnect()
                            task.cancel(timeoutConn)
                            if updateTextFunc then updateTextFunc() end
                            self:closeMore() 
                        end
                    end)
                end)

                local savedBind = ConfigManager.get("Keybinds")[commandId]
                if savedBind then
                    self:AddButton({
                        Info = { Title = "Remove Keybind [" .. savedBind .. "]" },
                        Callback = function()
                            KeybindManager.unbind(commandId)
                            if updateTextFunc then updateTextFunc() end
                            self:closeMore()
                        end
                    }, moreScrollFrame)
                end
            end

            if isStartup then
                local startupBtn = self:AddButton({
                    Info = { Title = "Toggle Startup" },
                    InternalInfo = { Toggle = true, UniqueCommandId = commandId .. "_startup" },
                    Callback = function(state) ConfigManager.set(commandId, state, "Startup") end
                }, moreScrollFrame)
                startupBtn.setVisualState(ConfigManager.get("Startup")[commandId] == true)
            end
        end

        tabData.tabObj = tabObj
        return tabObj
    end

    return Tab
end

__MODULES["config/ConfigManager"] = function()
    local ConfigManager = {}
    local HttpService = game:GetService("HttpService")
    local State = __REQUIRE("state")

    local cachedConfig = nil

    function ConfigManager.getPath()
        local folder = State.saveFolder ~= "" and (State.saveFolder .. "/") or ""
        return folder .. State.saveFileName .. ".json"
    end

    function ConfigManager.getDefault()
        return { 
            Startup = {}, 
            Keybinds = {}, 
            Settings = {
                GridSnap = true,
                GridSize = 15
            }, 
            TabPositions = {},
            MenuToggle = "RightShift",
            QuickCommandsToggle = "F2"
        }
    end

    function ConfigManager.load()
        if cachedConfig then return cachedConfig end

        if type(isfile) ~= "function" or not isfile(ConfigManager.getPath()) then 
            cachedConfig = ConfigManager.getDefault()
            return cachedConfig
        end

        local success, content = pcall(readfile, ConfigManager.getPath())
        if not success then return ConfigManager.getDefault() end

        local decSuccess, decoded = pcall(HttpService.JSONDecode, HttpService, content)
        cachedConfig = decSuccess and decoded or ConfigManager.getDefault()
        return cachedConfig
    end

    function ConfigManager.save(config)
        cachedConfig = config
        if type(writefile) ~= "function" then return false end

        if State.saveFolder ~= "" and type(isfolder) == "function" and not isfolder(State.saveFolder) then
            pcall(makefolder, State.saveFolder)
        end

        local success, encoded = pcall(HttpService.JSONEncode, HttpService, config)
        if not success then return false end
        return pcall(writefile, ConfigManager.getPath(), encoded)
    end

    function ConfigManager.set(key, value, dict)
        local config = ConfigManager.load()
        if dict then
            config[dict] = config[dict] or {}
            config[dict][key] = value
        else
            config[key] = value
        end
        ConfigManager.save(config)
    end

    function ConfigManager.get(dict)
        local config = ConfigManager.load()
        return dict and (config[dict] or {}) or config
    end

    return ConfigManager
end

__MODULES["config/KeybindManager"] = function()
    local KeybindManager = {}
    local ConfigManager = __REQUIRE("config/ConfigManager")
    local State = __REQUIRE("state")
    local UIS = game:GetService("UserInputService")

    KeybindManager.binds = {}
    local lastRebindTimestamp = 0

    UIS.InputBegan:Connect(function(input, gpe)
        if input.UserInputType == Enum.UserInputType.Keyboard then
            if UIS:GetFocusedTextBox() then return end

            for commandId, bindData in pairs(KeybindManager.binds) do
                if input.KeyCode == bindData.keyCode then
                    local btn = State.buttons[commandId]
                    if btn and btn.isToggle then
                        State.values[commandId] = not State.values[commandId]
                        if btn.setVisualState then
                            btn.setVisualState(State.values[commandId])
                        end
                        bindData.callback(State.values[commandId])
                    else
                        bindData.callback()
                    end
                end
            end
        end
    end)

    UIS.InputEnded:Connect(function(input, gpe)
        if input.UserInputType == Enum.UserInputType.Keyboard then
            if UIS:GetFocusedTextBox() then return end
            if (tick() - lastRebindTimestamp) < 0.3 then return end

            -- visibility toggle
            if State.menuToggleKeybind and input.KeyCode == State.menuToggleKeybind then
                if State.toggleTabs then
                    State.toggleTabs()
                end
                return
            end

            -- quick commands togle
            if State.quickCommandsKeybind and input.KeyCode == State.quickCommandsKeybind then
                if State.toggleQuickCommands then
                    State.toggleQuickCommands()
                end
                return
            end
        end
    end)

    function KeybindManager.bind(commandId, callback, keyCode)
        ConfigManager.set(commandId, keyCode.Name, "Keybinds")
        KeybindManager.binds[commandId] = { callback = callback, keyCode = keyCode }
    end

    function KeybindManager.unbind(commandId)
        ConfigManager.set(commandId, nil, "Keybinds")
        KeybindManager.binds[commandId] = nil
    end

    function KeybindManager.setMenuToggle(keyCode)
        lastRebindTimestamp = tick()
        ConfigManager.set("MenuToggle", keyCode.Name)
        State.menuToggleKeybind = keyCode
    end

    function KeybindManager.setQuickCommandsToggle(keyCode)
        lastRebindTimestamp = tick()
        ConfigManager.set("QuickCommandsToggle", keyCode.Name)
        State.quickCommandsKeybind = keyCode
    end

    return KeybindManager
end

__MODULES["constants"] = function()
    local Constants = {}

    Constants.Colors = {
        accent = Color3.new(0.667, 0, 1),
        dark = Color3.new(0.176, 0.176, 0.176),
        darkHover = Color3.new(0.156, 0.156, 0.156),
        gray = Color3.fromRGB(125, 125, 125),
        inputBg = Color3.new(0.118, 0.118, 0.118),
        text = Color3.new(1, 1, 1),
        textPlaceholder = Color3.new(0.7, 0.7, 0.7),
    }

    Constants.Fonts = {
        regular = Font.new("rbxasset://fonts/families/BuilderSans.json", Enum.FontWeight.Regular),
        medium = Font.new("rbxasset://fonts/families/BuilderSans.json", Enum.FontWeight.Medium),
    }

    function Constants.randomString(length)
        length = length or 24
        local rng = Random.new()
        local output = {}
        for i = 1, length do
            output[i] = string.char(rng:NextInteger(1, 250))
        end
        return table.concat(output)
    end

    function Constants.darkenColor(color, amount)
        return Color3.new(
            math.max(0, color.R - amount),
            math.max(0, color.G - amount),
            math.max(0, color.B - amount)
        )
    end

    return Constants
end

__MODULES["main"] = function()
    local Library = {}
    local State = __REQUIRE("state")
    local ConfigManager = __REQUIRE("config/ConfigManager")
    local KeybindManager = __REQUIRE("config/KeybindManager")
    local Tab = __REQUIRE("components/Tab")
    local Constants = __REQUIRE("constants")
    local QuickCommands = __REQUIRE("components/QuickCommands")
    local UIBuilder = __REQUIRE("utils/UIBuilder")
    local RunService = game:GetService("RunService")
    local UIS = game:GetService("UserInputService")
    local GuiService = game:GetService("GuiService")
    local TS = game:GetService("TweenService")

    local COREGUI = cloneref and cloneref(game:GetService("CoreGui")) or game:GetService("CoreGui")

    function Library.new(config)
        config = config or {}
        State.libName = config.Name or "Unnamed"
        State.saveFolder = config.SaveFolder or ""
        State.saveFileName = config.SaveId or "config"
        State.tabCount = 0
        State.tabOrder = {}

        State.mainGui = Instance.new("ScreenGui")
        State.mainGui.Name = Constants.randomString()
        State.mainGui.Parent = COREGUI
        State.mainGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
        State.mainGui.ResetOnSpawn = false
        State.mainGui.IgnoreGuiInset = true
        State.mainGui.DisplayOrder = 2147483647

        State.tabsContainer = Instance.new("Frame")
        State.tabsContainer.Name = "tabsContainer"
        State.tabsContainer.Size = UDim2.new(1, 0, 1, 0)
        State.tabsContainer.BackgroundTransparency = 1
        State.tabsContainer.Parent = State.mainGui

        State.overlayContainer = Instance.new("Frame")
        State.overlayContainer.Name = "overlayContainer"
        State.overlayContainer.Size = UDim2.new(1, 0, 1, 0)
        State.overlayContainer.BackgroundTransparency = 1
        State.overlayContainer.ZIndex = 100
        State.overlayContainer.Parent = State.mainGui

        -- tooltips
        State.tooltipGui = UIBuilder.create("TextLabel", {
            Name = "Tooltip",
            Visible = false,
            BackgroundColor3 = Constants.Colors.darkHover,
            TextColor3 = Constants.Colors.text,
            FontFace = Constants.Fonts.regular,
            TextSize = 13,
            Size = UDim2.new(0, 0, 0, 24),
            AutomaticSize = Enum.AutomaticSize.X,
            Parent = State.overlayContainer
        })
        UIBuilder.create("UICorner", { CornerRadius = UDim.new(0, 4), Parent = State.tooltipGui })
        UIBuilder.create("UIPadding", { PaddingLeft = UDim.new(0, 8), PaddingRight = UDim.new(0, 8), Parent = State.tooltipGui })

        -- tooltip positioning
        local hoverTime = 0
        local lastMousePos = Vector2.new()

        RunService.RenderStepped:Connect(function(dt)
            if not State.tooltipGui then return end

            if State.hoveredTooltipText then
                local currentPos = UIS:GetMouseLocation()
                if (currentPos - lastMousePos).Magnitude > 2 then
                    hoverTime = 0
                    lastMousePos = currentPos
                    State.tooltipGui.Visible = false
                else
                    hoverTime = hoverTime + dt
                    if hoverTime >= 1.0 and not State.tooltipGui.Visible then
                        State.tooltipGui.Text = State.hoveredTooltipText

                        local camera = workspace.CurrentCamera
                        local vp = camera and camera.ViewportSize or Vector2.new(1280, 720)
                        local tipWidth = State.tooltipGui.AbsoluteSize.X
                        if tipWidth == 0 then
                            tipWidth = State.tooltipGui.TextBounds.X + 20
                        end
                        local tipHeight = 24

                        -- flip to left of cursor
                        local posX = currentPos.X + 12
                        if posX + tipWidth > vp.X - 10 then
                            posX = currentPos.X - tipWidth - 12
                        end
                        posX = math.clamp(posX, 10, math.max(10, vp.X - tipWidth - 10))

                        -- flip to top of cursor
                        local posY = currentPos.Y + 12
                        if posY + tipHeight > vp.Y - 10 then
                            posY = currentPos.Y - tipHeight - 12
                        end
                        local topInset = GuiService:GetGuiInset().Y
                        posY = math.clamp(posY, topInset + 5, math.max(topInset + 5, vp.Y - tipHeight - 10))

                        State.tooltipGui.Position = UDim2.new(0, posX, 0, posY)
                        State.tooltipGui.Visible = true
                        State.tooltipGui.ZIndex = State.getHighestZ() + 100
                    end
                end
            else
                hoverTime = 0
                State.tooltipGui.Visible = false
            end
        end)

        local savedConfig = ConfigManager.get()
        local menuKey = savedConfig.MenuToggle or "RightShift"
        if Enum.KeyCode[menuKey] then
            KeybindManager.setMenuToggle(Enum.KeyCode[menuKey])
        end

        local qcKey = savedConfig.QuickCommandsToggle or "F2"
        if Enum.KeyCode[qcKey] then
            KeybindManager.setQuickCommandsToggle(Enum.KeyCode[qcKey])
        end

        QuickCommands.init()

        State.isUiVisible = true
        State.toggleTabs = function(forcedState)
            if forcedState ~= nil then
                State.isUiVisible = forcedState
            else
                State.isUiVisible = not State.isUiVisible
            end
            State.tabsContainer.Visible = State.isUiVisible
            if not State.isUiVisible then
                State.hideAllMoreScrolls()
            end
        end

        local app = {}

        function app:CreateTab(name, pos)
            if State.tabs[name] and State.tabs[name].tabObj then
                return State.tabs[name].tabObj
            end
            return Tab.create(name, pos)
        end

        function app:GetTab(name)
            local tabData = State.tabs[name]
            return tabData and tabData.tabObj or nil
        end

        function app:ToggleGui(forcedState)
            State.toggleTabs(forcedState)
        end

        -- make built in settings
        local settingsTab = app:CreateTab("Settings")

        local currentMenuKeyName = ConfigManager.get().MenuToggle or "RightShift"
        local menuKeyBtn = settingsTab:AddButton({
            Info = { 
                Title = "UI Visibility Keybind [" .. currentMenuKeyName .. "]", 
                Description = "Click to rebind the key used to show/hide the UI tabs." 
            },
            Callback = function() end
        })

        local isRebindingMenu = false
        menuKeyBtn.button.Activated:Connect(function()
            if isRebindingMenu then return end
            isRebindingMenu = true
            menuKeyBtn.text.Text = "Press a key (5s timeout)..."
            menuKeyBtn.text.TextColor3 = Constants.Colors.accent

            local conn, timeout
            local function finish(newKey)
                if conn then conn:Disconnect(); conn = nil end
                if timeout then task.cancel(timeout); timeout = nil end
                isRebindingMenu = false
                local keyName = newKey and newKey.Name or (ConfigManager.get().MenuToggle or "RightShift")
                menuKeyBtn.text.Text = "UI Visibility Keybind [" .. keyName .. "]"
                menuKeyBtn.text.TextColor3 = Constants.Colors.text
            end

            timeout = task.delay(5, function() finish(nil) end)
            conn = UIS.InputBegan:Connect(function(input)
                if UIS:GetFocusedTextBox() then return end
                if input.UserInputType == Enum.UserInputType.Keyboard then
                    if input.KeyCode == Enum.KeyCode.Escape then
                        finish(nil)
                    else
                        KeybindManager.setMenuToggle(input.KeyCode)
                        finish(input.KeyCode)
                    end
                end
            end)
        end)

        -- quick commands bind
        local currentQCKeyName = ConfigManager.get().QuickCommandsToggle or "F2"
        local qcKeyBtn = settingsTab:AddButton({
            Info = { 
                Title = "Quick Commands Keybind [" .. currentQCKeyName .. "]", 
                Description = "Click to rebind the key used to open Quick Commands." 
            },
            Callback = function() end
        })

        local isRebindingQC = false
        qcKeyBtn.button.Activated:Connect(function()
            if isRebindingQC then return end
            isRebindingQC = true
            qcKeyBtn.text.Text = "Press a key (5s timeout)..."
            qcKeyBtn.text.TextColor3 = Constants.Colors.accent

            local conn, timeout
            local function finish(newKey)
                if conn then conn:Disconnect(); conn = nil end
                if timeout then task.cancel(timeout); timeout = nil end
                isRebindingQC = false
                local keyName = newKey and newKey.Name or (ConfigManager.get().QuickCommandsToggle or "F2")
                qcKeyBtn.text.Text = "Quick Commands Keybind [" .. keyName .. "]"
                qcKeyBtn.text.TextColor3 = Constants.Colors.text
            end

            timeout = task.delay(5, function() finish(nil) end)
            conn = UIS.InputBegan:Connect(function(input)
                if UIS:GetFocusedTextBox() then return end
                if input.UserInputType == Enum.UserInputType.Keyboard then
                    if input.KeyCode == Enum.KeyCode.Escape then
                        finish(nil)
                    else
                        KeybindManager.setQuickCommandsToggle(input.KeyCode)
                        finish(input.KeyCode)
                    end
                end
            end)
        end)

        -- grid snap
        local currentGridSnap = (ConfigManager.get("Settings") or {}).GridSnap ~= false
        local gridSnapBtn = settingsTab:AddButton({
            Info = {
                Title = "Grid Snapping",
                Description = "Enables magnetic snapping when moving tabs."
            },
            InternalInfo = {
                Toggle = true,
                UniqueCommandId = "setting_gridsnap"
            },
            Callback = function(enabled)
                ConfigManager.set("GridSnap", enabled, "Settings")
            end
        })
        gridSnapBtn.setVisualState(currentGridSnap)

        -- grid size slider
        local currentGridSize = (ConfigManager.get("Settings") or {}).GridSize or 15
        settingsTab:AddSlider({
            Info = {
                Title = "Grid Snap Size",
                Description = "Sets how many pixels between each magnetic grid line."
            },
            InternalInfo = {
                UniqueCommandId = "setting_gridsize",
                Save = true
            },
            Min = 5,
            Max = 30,
            Default = currentGridSize,
            Step = 5,
            Callback = function(val)
                ConfigManager.set("GridSize", val, "Settings")
            end
        })

        -- reset tabs pos
        settingsTab:AddButton({
            Info = {
                Title = "Reset Tab Positions",
                Description = "Restores all tabs to their exact initial order below the top bar."
            },
            Callback = function()
                ConfigManager.set("TabPositions", {})
                local topInset = GuiService:GetGuiInset().Y
                for index, tabName in ipairs(State.tabOrder) do
                    local tabData = State.tabs[tabName]
                    if tabData and tabData.frame then
                        local yOffset = topInset + 10 + ((index - 1) * 26)
                        local targetPos = UDim2.new(0, 15, 0, yOffset)
                        TS:Create(tabData.frame, TweenInfo.new(0.35, Enum.EasingStyle.Exponential, Enum.EasingDirection.Out), {
                            Position = targetPos
                        }):Play()
                    end
                end
            end
        })

        return app
    end

    return Library
end

__MODULES["state"] = function()
    local State = {
        libName = "Unnamed",
        saveFolder = "",
        saveFileName = "config",

        mainGui = nil,
        tabsContainer = nil,
        overlayContainer = nil,
        isUiVisible = true,

        tabCount = 0,
        tabOrder = {},
        tabs = {},
        values = {},
        buttons = {},
        menuToggleKeybind = nil,
        quickCommandsKeybind = nil,

        commands = {},

        toggleTabs = nil,
        toggleQuickCommands = nil,

        tooltipGui = nil,
        hoveredTooltipText = nil,
    }

    function State.getValue(commandId)
        return State.values[commandId]
    end

    function State.setValue(commandId, value)
        State.values[commandId] = value
    end

    function State.registerCommand(data)
        State.commands[data.id] = data
    end

    function State.getHighestZ()
        local highest = 0
        if State.tabsContainer then
            for _, obj in ipairs(State.tabsContainer:GetChildren()) do
                if obj:IsA("GuiObject") then
                    highest = math.max(highest, obj.ZIndex)
                end
            end
        end
        return highest
    end

    function State.hideAllMoreScrolls(exceptTabName, exceptOwner)
        for tabName, tabData in pairs(State.tabs) do
            if tabData.moreScroll then
                local keepOpen = (tabName == exceptTabName) and (tabData.moreScroll:GetAttribute("Owner") == exceptOwner)
                if not keepOpen and tabData.closeMoreFunc then
                    tabData.closeMoreFunc()
                end
            end
        end
    end

    function State.showTooltip(text)
        State.hoveredTooltipText = text
    end

    function State.hideTooltip(text)
        if State.hoveredTooltipText == text then
            State.hoveredTooltipText = nil
        end
    end

    return State
end

__MODULES["utils/UIBuilder"] = function()
    local UIBuilder = {}
    local Constants = __REQUIRE("constants")

    function UIBuilder.create(className, properties)
        local inst = Instance.new(className)
        for k, v in pairs(properties or {}) do
            inst[k] = v
        end
        return inst
    end

    function UIBuilder.createGradient(parent)
        local frame = UIBuilder.create("Frame", {
            Name = "gradient",
            Visible = false,
            AnchorPoint = Vector2.new(0.5, 0.5),
            BackgroundColor3 = Color3.new(1, 1, 1),
            Position = UDim2.new(0.5, 0, 0.5, 0),
            BorderSizePixel = 0,
            Size = UDim2.new(1, 0, 1, 0),
            ZIndex = 2,
            Parent = parent,
        })

        UIBuilder.create("UIGradient", {
            Transparency = NumberSequence.new({
                NumberSequenceKeypoint.new(0, 1),
                NumberSequenceKeypoint.new(0, 1),
                NumberSequenceKeypoint.new(1, 0.9)
            }),
            Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, Constants.Colors.accent),
                ColorSequenceKeypoint.new(1, Constants.Colors.accent)
            }),
            Parent = frame
        })

        return frame
    end

    return UIBuilder
end

return __REQUIRE("main")
